#!/usr/bin/env python3
"""Write (or with --check, verify) docs/ERRORS.md from src/errors.py."""
from __future__ import annotations

from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "src"))
import errors  # noqa: E402

DOC = ROOT / "docs" / "ERRORS.md"


def render() -> str:
    lines = [
        "# SmoothCast error catalogue", "",
        "<!-- Generated by scripts/ci/gen_errors_doc.py from src/errors.py. Do not edit. -->", "",
        "Every failure a person can see has a stable code, a plain message and ordered steps.",
        "Codes are never translated. See [UX copy](UX_COPY.md) for the voice.", "",
    ]
    for spec in errors.CATALOGUE.values():
        retry = "yes" if spec.retryable else "no"
        lines += [f'<a id="{spec.docs_anchor}"></a>', f"## `{spec.code}`", "",
                  f"- Severity: {spec.severity}; retryable: {retry}",
                  f"- Message: {spec.message}", "- Try:"]
        lines += [f"  {i}. {step}" for i, step in enumerate(spec.steps, 1)]
        lines.append("")
    return "\n".join(lines)


def main(argv: list[str]) -> int:
    text = render()
    if "--check" in argv:
        if not DOC.exists() or DOC.read_text(encoding="utf-8") != text:
            print("docs/ERRORS.md is stale: run python3 scripts/ci/gen_errors_doc.py")
            return 1
        return 0
    DOC.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
